"      <span style=\"position: absolute; left: 10px; bottom: 10px; font-size: 11.5px; color: #574E42; background: #FBF8F2; padding: 3px 6px; border-radius: 4px;\">[Map · tap to open]</span>\n    </div>\n\n    <span style=\"font-size: 12px; color: #6B6154; letter-spacing: 0.03em;\">IRON</span>\n    <p style=\"margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 20px; line-height: 1.4;\">Iron-working appears across West Africa and the Nile valley in the first millennium BCE. Whether it began here or arrived from elsewhere is argued both ways.</p>\n    <div style=\"display: flex; gap: 8px; align-items: center; font-size: 12px; color: #574E42;\">\n      <span style=\"display: inline-block; width: 28px; border-top: 2px dashed #574E42;\"></span>\n      <span>contested · two readings</span>\n    </div>\n\n    <div style=\"display: flex; gap: 12px; align-items: center; padding: 10px; background: #FBF8F2; border-radius: 8px;\">\n      <div role=\"img\" aria-label=\"Image placeholder\" style=\"width: 56px; height: 56px; flex-shrink: 0; border-radius: 6px; background: repeating-linear-gradient(135deg, #D8CDB9 0 8px, #D2C6B0 8px 16px);\"></div>\n",
"      <div style=\"display: flex; flex-direction: column; gap: 2px;\">\n        <span style=\"font-family: 'Newsreader', Georgia, serif; font-size: 15px;\">Nok terracotta figure</span>\n        <span style=\"font-size: 12px; color: #574E42;\">Tap for the object story</span>\n      </div>\n    </div>\n\n    <div style=\"display: flex; gap: 8px; margin-top: auto; padding-bottom: 12px;\">\n      <button type=\"button\" style=\"flex-grow: 1; height: 48px; border: 1px solid #DCD3C4; border-radius: 10px; background: #FFFFFF; font-size: 15px; color: #1E1A15;\">Back</button>\n      <button type=\"button\" style=\"flex-grow: 2; height: 48px; border: 0; border-radius: 10px; background: #A0431F; color: #FFFFFF; font-size: 15px; font-weight: 500;\">Next: Brass and casting</button>\n    </div>\n  </main>\n\n  <nav aria-label=\"Sections\" style=\"height: 64px; box-sizing: border-box; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-top: 1px solid #DCD3C4; background: #FBF8F2;\">\n    <button type=\"button\" aria-current=\"page\" style=\"border: 0; background: transparent; font-size: 12px; font-weight: 600; color: #A0431F; border-top: 2px solid #A0431F;\">Unit</button>\n",
"    <button type=\"button\" style=\"border: 0; background: transparent; font-size: 12px; color: #574E42; border-top: 2px solid transparent;\">Atlas</button>\n    <button type=\"button\" style=\"border: 0; background: transparent; font-size: 12px; color: #574E42; border-top: 2px solid transparent;\">Record</button>\n    <button type=\"button\" style=\"border: 0; background: transparent; font-size: 12px; color: #574E42; border-top: 2px solid transparent;\">Historian</button>\n  </nav>\n</div>\n</x-dc>\n<script type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":390,\"height\":844}}'>\nclass Component extends DCLogic {\n  renderVals() { return {}; }\n}\n</script>\n</body>\n</html>\n"
],
