"<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<title>F1.13 Networks — desk</title>\n<script src=\"./support.js\"></script>\n</head>\n<body>\n<x-dc>\n<helmet>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=IBM+Plex+Sans:wght@400;500;600&amp;family=Newsreader:opsz,wght@6..72,400;6..72,500;6..72,600&amp;display=swap\">\n<style>\nbody{margin:0;background:#15130F;font-family:'IBM Plex Sans',system-ui,sans-serif;color:#1E1A15}\na{color:#2F4470}a:hover{color:#1C2B4A}\nbutton{font-family:inherit}\n</style>\n</helmet>\n<div style=\"width: 1440px; height: 900px; box-sizing: border-box; display: flex; flex-direction: column; background: #15130F; color: #1E1A15; font-family: 'IBM Plex Sans', system-ui, sans-serif;\">\n\n  <header style=\"height: 56px; box-sizing: border-box; padding: 0 24px; display: flex; align-items: center; gap: 24px; border-bottom: 1px solid #DCD3C4; background: #FBF8F2;\">\n    <div style=\"display: flex; flex-direction: column; gap: 2px; width: 260px;\">\n      <span style=\"font-size: 12px; color: #6B6154; letter-spacing: 0.04em; text-transform: uppercase;\">Module F1</span>\n",
"      <span style=\"font-family: 'Newsreader', Georgia, serif; font-size: 18px; font-weight: 600;\">Histories of making</span>\n    </div>\n    <nav aria-label=\"Module path\" style=\"flex-grow: 1; display: flex; align-items: center; gap: 12px;\">\n      <span style=\"font-size: 13px; color: #574E42; white-space: nowrap;\">Unit 13 of 35</span>\n      <div style=\"display: flex; gap: 3px; align-items: center;\">\n        <sc-for list=\"{{units}}\" as=\"t\" hint-placeholder-count=\"35\">\n          <span style=\"display: block; width: 12px; height: 6px; border-radius: 3px; background: {{t.bg}};\"></span>\n        </sc-for>\n      </div>\n    </nav>\n    <div style=\"display: flex; gap: 8px; align-items: center;\">\n      <span style=\"font-size: 13px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; color: #574E42;\">Route: Maker</span>\n      <span style=\"font-size: 13px; padding: 6px 10px; border: 1px solid #DCD3C4; border-radius: 999px; color: #574E42;\">Practice</span>\n      <button type=\"button\" style=\"height: 36px; padding: 0 14px; border: 1px solid #DCD3C4; background: #FFFFFF; border-radius: 8px; font-size: 14px; color: #1E1A15;\">Glossary</button>\n",
"      <button type=\"button\" style=\"height: 36px; padding: 0 14px; border: 1px solid #A0431F; background: #FFFFFF; border-radius: 8px; font-size: 14px; color: #1E1A15;\">Sources record · 14</button>\n    </div>\n  </header>\n\n  <div style=\"flex-grow: 1; display: flex; min-height: 0;\">\n\n    <section aria-label=\"Atlas\" style=\"width: 960px; box-sizing: border-box; position: relative; background: #15130F; display: flex; flex-direction: column;\">\n      <div style=\"padding: 16px 20px; display: flex; justify-content: space-between; align-items: center;\">\n        <div role=\"group\" aria-label=\"Atlas views\" style=\"display: flex; gap: 4px; background: #24201A; border: 1px solid #3A342B; border-radius: 10px; padding: 4px;\">\n          <button type=\"button\" aria-pressed=\"true\" style=\"height: 32px; padding: 0 12px; border: 0; border-radius: 7px; background: #EDE6D8; color: #15130F; font-size: 13px;\">Globe</button>\n          <button type=\"button\" style=\"height: 32px; padding: 0 12px; border: 0; border-radius: 7px; background: transparent; color: #CFC5B2; font-size: 13px;\">Map</button>\n",
"          <button type=\"button\" style=\"height: 32px; padding: 0 12px; border: 0; border-radius: 7px; background: transparent; color: #CFC5B2; font-size: 13px;\">Timeline</button>\n          <button type=\"button\" style=\"height: 32px; padding: 0 12px; border: 0; border-radius: 7px; background: transparent; color: #CFC5B2; font-size: 13px;\">Occurrences</button>\n          <button type=\"button\" style=\"height: 32px; padding: 0 12px; border: 0; border-radius: 7px; background: transparent; color: #CFC5B2; font-size: 13px;\">Connections</button>\n          <button type=\"button\" style=\"height: 32px; padding: 0 12px; border: 0; border-radius: 7px; background: transparent; color: #CFC5B2; font-size: 13px;\">Story</button>\n          <button type=\"button\" style=\"height: 32px; padding: 0 12px; border: 0; border-radius: 7px; background: transparent; color: #CFC5B2; font-size: 13px;\">Lineage</button>\n        </div>\n        <span style=\"font-size: 12px; color: #B5AA96;\">[Illustrative routes — the route record decides]</span>\n      </div>\n\n      <div style=\"flex-grow: 1; position: relative;\">\n",
"        <svg width=\"920\" height=\"620\" viewBox=\"0 0 920 620\" role=\"img\" aria-label=\"Globe with the bowl's route from Jingdezhen to Cairo and a later leg around the Cape to Amsterdam\" style=\"position: absolute; left: 20px; top: 0;\">\n          <circle cx=\"460\" cy=\"320\" r=\"290\" fill=\"#1D1A15\" stroke=\"#3A342B\" stroke-width=\"1.5\"></circle>\n          <ellipse cx=\"460\" cy=\"320\" rx=\"251\" ry=\"290\" fill=\"none\" stroke=\"#2C2821\" stroke-width=\"1\"></ellipse>\n          <ellipse cx=\"460\" cy=\"320\" rx=\"145\" ry=\"290\" fill=\"none\" stroke=\"#2C2821\" stroke-width=\"1\"></ellipse>\n          <line x1=\"460\" y1=\"30\" x2=\"460\" y2=\"610\" stroke=\"#2C2821\" stroke-width=\"1\"></line>\n          <line x1=\"170\" y1=\"320\" x2=\"750\" y2=\"320\" stroke=\"#2C2821\" stroke-width=\"1\"></line>\n          <line x1=\"209\" y1=\"175\" x2=\"711\" y2=\"175\" stroke=\"#2C2821\" stroke-width=\"1\"></line>\n          <line x1=\"209\" y1=\"465\" x2=\"711\" y2=\"465\" stroke=\"#2C2821\" stroke-width=\"1\"></line>\n          <line x1=\"315\" y1=\"69\" x2=\"605\" y2=\"69\" stroke=\"#2C2821\" stroke-width=\"1\"></line>\n          <line x1=\"315\" y1=\"571\" x2=\"605\" y2=\"571\" stroke=\"#2C2821\" stroke-width=\"1\"></line>\n\n",
"          <path d=\"M508 158 Q610 120 707 179\" fill=\"none\" stroke=\"#9FB3D9\" stroke-width=\"2\" stroke-dasharray=\"10 6\"></path>\n          <path d=\"M422 175 Q465 150 508 158\" fill=\"none\" stroke=\"#CFC5B2\" stroke-width=\"2\" stroke-dasharray=\"2 5\" stroke-linecap=\"round\"></path>\n\n          <path d=\"M707 179 Q716 186 718 198\" fill=\"none\" stroke=\"#D9A25C\" stroke-width=\"3\"></path>\n          <path d=\"M718 198 Q690 250 626 263\" fill=\"none\" stroke=\"#D9A25C\" stroke-width=\"3\"></path>\n          <path d=\"M626 263 Q590 215 533 188\" fill=\"none\" stroke=\"#D9A25C\" stroke-width=\"3\"></path>\n          <path d=\"M533 188 Q480 170 422 175\" fill=\"none\" stroke=\"#D9A25C\" stroke-width=\"3\" opacity=\"0.45\"></path>\n          <path d=\"M626 263 Q560 420 372 484\" fill=\"none\" stroke=\"#D9A25C\" stroke-width=\"3\" opacity=\"0.45\"></path>\n          <path d=\"M372 484 Q280 300 358 90\" fill=\"none\" stroke=\"#D9A25C\" stroke-width=\"3\" opacity=\"0.45\"></path>\n\n          <circle cx=\"224\" cy=\"246\" r=\"3.5\" fill=\"#EDE6D8\"></circle>\n          <circle cx=\"212\" cy=\"251\" r=\"3.5\" fill=\"#EDE6D8\"></circle>\n          <circle cx=\"200\" cy=\"257\" r=\"3.5\" fill=\"#EDE6D8\"></circle>\n          <circle cx=\"188\" cy=\"262\" r=\"3.5\" fill=\"#EDE6D8\"></circle>\n",
"          <circle cx=\"178\" cy=\"267\" r=\"3.5\" fill=\"#EDE6D8\"></circle>\n          <text x=\"160\" y=\"232\" fill=\"#EDE6D8\" font-size=\"12\" font-family=\"IBM Plex Sans, sans-serif\">People — content note</text>\n\n          <circle cx=\"707\" cy=\"179\" r=\"6\" fill=\"#D9A25C\"></circle>\n          <circle cx=\"718\" cy=\"198\" r=\"6\" fill=\"#D9A25C\"></circle>\n          <circle cx=\"626\" cy=\"263\" r=\"6\" fill=\"#D9A25C\"></circle>\n          <circle cx=\"533\" cy=\"188\" r=\"12\" fill=\"none\" stroke=\"#EDE6D8\" stroke-width=\"2\"></circle>\n          <circle cx=\"533\" cy=\"188\" r=\"6\" fill=\"#EDE6D8\"></circle>\n          <circle cx=\"422\" cy=\"175\" r=\"5\" fill=\"#8A7A5E\"></circle>\n          <circle cx=\"372\" cy=\"484\" r=\"5\" fill=\"#8A7A5E\"></circle>\n          <circle cx=\"358\" cy=\"90\" r=\"5\" fill=\"#8A7A5E\"></circle>\n          <circle cx=\"508\" cy=\"158\" r=\"5\" fill=\"#9FB3D9\"></circle>\n\n          <text x=\"720\" y=\"172\" fill=\"#EDE6D8\" font-size=\"13\" font-family=\"IBM Plex Sans, sans-serif\">Jingdezhen</text>\n          <text x=\"728\" y=\"206\" fill=\"#CFC5B2\" font-size=\"12\" font-family=\"IBM Plex Sans, sans-serif\">Quanzhou</text>\n          <text x=\"638\" y=\"280\" fill=\"#CFC5B2\" font-size=\"12\" font-family=\"IBM Plex Sans, sans-serif\">Calicut</text>\n",
"          <text x=\"496\" y=\"152\" fill=\"#9FB3D9\" font-size=\"12\" font-family=\"IBM Plex Sans, sans-serif\">Kashan</text>\n          <text x=\"380\" y=\"166\" fill=\"#B5AA96\" font-size=\"12\" font-family=\"IBM Plex Sans, sans-serif\">Cairo</text>\n          <text x=\"300\" y=\"506\" fill=\"#B5AA96\" font-size=\"12\" font-family=\"IBM Plex Sans, sans-serif\">Cape of Good Hope</text>\n          <text x=\"370\" y=\"86\" fill=\"#B5AA96\" font-size=\"12\" font-family=\"IBM Plex Sans, sans-serif\">Amsterdam</text>\n        </svg>\n\n        <div style=\"position: absolute; left: 600px; top: 110px; width: 300px; padding: 16px 18px; background: #FBF8F2; border-radius: 10px; display: flex; flex-direction: column; gap: 8px;\">\n          <span style=\"font-size: 12px; color: #6B6154; letter-spacing: 0.03em;\">STOP 4 OF 7 · HORMUZ</span>\n          <span style=\"font-size: 12px; color: #574E42;\">[date range from the route record]</span>\n          <div style=\"display: flex; flex-direction: column; gap: 6px; font-size: 13px; line-height: 1.4;\">\n            <span><span style=\"font-weight: 600;\">Joined the cargo:</span> [from the route record]</span>\n",
"            <span><span style=\"font-weight: 600;\">Paid here:</span> [from the route record]</span>\n            <span><span style=\"font-weight: 600;\">Called here:</span> [local name, from the record]</span>\n          </div>\n          <div style=\"display: flex; gap: 8px; margin-top: 4px;\">\n            <button type=\"button\" style=\"flex-grow: 1; height: 40px; border: 1px solid #DCD3C4; border-radius: 8px; background: #FFFFFF; font-size: 13px; color: #1E1A15;\">Previous stop</button>\n            <button type=\"button\" style=\"flex-grow: 1; height: 40px; border: 0; border-radius: 8px; background: #1E1A15; color: #FBF8F2; font-size: 13px;\">Next stop</button>\n          </div>\n        </div>\n\n        <div aria-label=\"Legend\" style=\"position: absolute; left: 24px; bottom: 16px; padding: 12px 14px; background: #24201A; border: 1px solid #3A342B; border-radius: 10px; display: flex; flex-direction: column; gap: 6px; font-size: 12px; color: #EDE6D8;\">\n          <span style=\"display: flex; align-items: center; gap: 8px;\"><span style=\"display: inline-block; width: 28px; border-top: 3px solid #D9A25C;\"></span>Goods — the bowl's route</span>\n",
"          <span style=\"display: flex; align-items: center; gap: 8px;\"><span style=\"display: inline-block; width: 28px; border-top: 2px dashed #9FB3D9;\"></span>Materials</span>\n          <span style=\"display: flex; align-items: center; gap: 8px;\"><span style=\"display: inline-block; width: 28px; border-top: 2px dotted #CFC5B2;\"></span>Skills</span>\n          <span style=\"display: flex; align-items: center; gap: 8px;\"><span style=\"display: inline-flex; gap: 3px; width: 28px;\"><span style=\"width: 5px; height: 5px; border-radius: 50%; background: #EDE6D8;\"></span><span style=\"width: 5px; height: 5px; border-radius: 50%; background: #EDE6D8;\"></span><span style=\"width: 5px; height: 5px; border-radius: 50%; background: #EDE6D8;\"></span></span>People, never drawn as goods</span>\n        </div>\n      </div>\n\n      <div aria-label=\"Time-lapse\" style=\"padding: 12px 20px 16px; display: flex; align-items: center; gap: 14px; border-top: 1px solid #3A342B;\">\n        <button type=\"button\" aria-label=\"Play time-lapse\" style=\"width: 44px; height: 44px; border-radius: 50%; border: 0; background: #EDE6D8; display: flex; align-items: center; justify-content: center;\">\n",
"          <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"#15130F\" aria-hidden=\"true\"><path d=\"M7 4v16l13-8z\"></path></svg>\n        </button>\n        <div style=\"flex-grow: 1; display: flex; flex-direction: column; gap: 6px;\">\n          <div style=\"position: relative; height: 10px;\">\n            <div style=\"position: absolute; left: 0; right: 0; top: 4px; height: 2px; background: #3A342B;\"></div>\n            <div style=\"position: absolute; left: 0; width: 46%; top: 4px; height: 2px; background: #D9A25C;\"></div>\n            <div style=\"position: absolute; left: 46%; top: 0; width: 10px; height: 10px; border-radius: 50%; background: #EDE6D8;\"></div>\n          </div>\n          <div style=\"display: flex; justify-content: space-between; font-size: 12px; color: #B5AA96;\">\n            <span>1300</span><span>1400</span><span>1500</span><span>1600</span><span>1700</span>\n          </div>\n        </div>\n        <span style=\"font-size: 13px; color: #EDE6D8; padding: 6px 10px; border: 1px solid #3A342B; border-radius: 999px;\">Reduced motion: stepped</span>\n      </div>\n    </section>\n\n",
"    <section aria-label=\"Unit\" style=\"width: 480px; box-sizing: border-box; background: #FBF8F2; padding: 22px 28px; display: flex; flex-direction: column; gap: 14px; overflow: hidden;\">\n      <div style=\"font-size: 12px; color: #6B6154; letter-spacing: 0.03em;\">F1.13 · PRACTICE · ABOUT 60 MIN · OPENS ON DATA</div>\n      <h1 style=\"margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 30px; line-height: 1.12; font-weight: 500;\">Networks: objects, materials and skills</h1>\n\n      <div style=\"padding: 10px 12px; border-radius: 8px; background: #F3EDE3; font-size: 13px; line-height: 1.45;\">\n        <span style=\"font-weight: 600;\">Your guess:</span> Lisbon. <span style=\"font-weight: 600;\">The route in this record ends:</span> Amsterdam, by way of the Cape.\n      </div>\n\n      <div style=\"display: flex; flex-direction: column; gap: 6px;\">\n        <span style=\"font-size: 12px; color: #6B6154; letter-spacing: 0.03em;\">CARRY AN OBJECT · BLUE-AND-WHITE BOWL</span>\n        <div style=\"display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px;\">\n",
"          <span style=\"height: 28px; border-radius: 6px; background: #D9A25C; color: #1E1A15; font-size: 12px; display: flex; align-items: center; justify-content: center;\">1</span>\n          <span style=\"height: 28px; border-radius: 6px; background: #D9A25C; color: #1E1A15; font-size: 12px; display: flex; align-items: center; justify-content: center;\">2</span>\n          <span style=\"height: 28px; border-radius: 6px; background: #D9A25C; color: #1E1A15; font-size: 12px; display: flex; align-items: center; justify-content: center;\">3</span>\n          <span style=\"height: 28px; border-radius: 6px; background: #1E1A15; color: #FBF8F2; font-size: 12px; font-weight: 600; display: flex; align-items: center; justify-content: center;\">4</span>\n          <span style=\"height: 28px; border-radius: 6px; border: 1px solid #C9BCA4; color: #574E42; font-size: 12px; display: flex; align-items: center; justify-content: center;\">5</span>\n          <span style=\"height: 28px; border-radius: 6px; border: 1px solid #C9BCA4; color: #574E42; font-size: 12px; display: flex; align-items: center; justify-content: center;\">6</span>\n",
"          <span style=\"height: 28px; border-radius: 6px; border: 1px solid #C9BCA4; color: #574E42; font-size: 12px; display: flex; align-items: center; justify-content: center;\">7</span>\n        </div>\n      </div>\n\n      <div style=\"display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px;\">\n        <div style=\"padding: 12px; border: 1px solid #DCD3C4; border-radius: 8px; background: #FFFFFF; display: flex; flex-direction: column; gap: 4px;\">\n          <span style=\"font-size: 11.5px; color: #6B6154;\">CLAIM</span>\n          <span style=\"font-family: 'Newsreader', Georgia, serif; font-size: 17px; line-height: 1.25;\">Objects made the routes</span>\n          <span style=\"font-size: 12px; color: #574E42;\">[one case from the world set]</span>\n        </div>\n        <div style=\"padding: 12px; border: 1px solid #DCD3C4; border-radius: 8px; background: #FFFFFF; display: flex; flex-direction: column; gap: 4px;\">\n          <span style=\"font-size: 11.5px; color: #6B6154;\">COUNTER-CLAIM</span>\n          <span style=\"font-family: 'Newsreader', Georgia, serif; font-size: 17px; line-height: 1.25;\">Routes made the objects</span>\n",
"          <span style=\"font-size: 12px; color: #574E42;\">[one case from the world set]</span>\n        </div>\n      </div>\n\n      <div style=\"display: flex; gap: 10px; align-items: flex-start; padding: 10px 12px; border: 1px solid #C9A77A; background: #F7EEDC; border-radius: 8px; font-size: 13px; line-height: 1.45;\">\n        <svg width=\"18\" height=\"18\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#7A5A1E\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\" style=\"flex-shrink: 0; margin-top: 1px;\"><circle cx=\"12\" cy=\"12\" r=\"9\"></circle><path d=\"M12 8v5M12 16.5v.5\"></path></svg>\n        <span>The Atlantic route carried people. It opens with a content note, and people are shown as people, with names where the record has them.</span>\n      </div>\n\n      <div style=\"display: flex; flex-direction: column; gap: 8px;\">\n        <div role=\"tablist\" aria-label=\"Lane\" style=\"display: flex; gap: 4px; border-bottom: 1px solid #DCD3C4;\">\n          <button type=\"button\" role=\"tab\" aria-selected=\"true\" style=\"height: 36px; padding: 0 14px; border: 0; border-bottom: 2px solid #A0431F; background: transparent; font-size: 14px; color: #1E1A15;\">Maker</button>\n",
"          <button type=\"button\" role=\"tab\" aria-selected=\"false\" style=\"height: 36px; padding: 0 14px; border: 0; border-bottom: 2px solid transparent; background: transparent; font-size: 14px; color: #574E42;\">Briefer</button>\n        </div>\n        <p style=\"margin: 0; font-size: 14px; line-height: 1.5;\">Trace one object from your own world set end to end, and note where it changed hands.</p>\n        <div style=\"display: flex; gap: 8px;\">\n          <button type=\"button\" style=\"height: 44px; padding: 0 18px; border: 0; border-radius: 8px; background: #A0431F; color: #FFFFFF; font-size: 14px; font-weight: 500;\">Trace my object</button>\n          <button type=\"button\" style=\"height: 44px; padding: 0 18px; border: 1px solid #DCD3C4; border-radius: 8px; background: #FFFFFF; color: #1E1A15; font-size: 14px;\">Connect two things</button>\n        </div>\n      </div>\n    </section>\n  </div>\n</div>\n</x-dc>\n<script type=\"text/x-dc\" data-dc-script data-props='{\"$preview\":{\"width\":1440,\"height\":900}}'>\nclass Component extends DCLogic {\n  renderVals() {\n    const units = [];\n    for (let i = 0; i < 35; i++) {\n      units.push({ bg: i === 12 ? '#A0431F' : (i < 12 ? '#8C8173' : '#D2C6B0') });\n",
"    }\n    return { units };\n  }\n}\n</script>\n</body>\n</html>\n"
],
